const trig = $('When Executed by Another Workflow').first().json;
const str = (v) => (v === undefined || v === null) ? '' : String(v);

let cases = $('Get Cases').all().map(i => i.json).filter(x => x && x.Id);
let tickets = $input.all().map(i => i.json).filter(x =>
  x && (x.external_id !== undefined || x.order_id !== undefined || x.last_status !== undefined));

const ref = str(trig.order_id).trim().toLowerCase();
const want = str(trig.case_number).trim().toLowerCase();

if (want !== '') {
  cases = cases.filter(x => str(x.CaseNumber).toLowerCase() === want || str(x.Id).toLowerCase() === want);
}
if (ref !== '') {
  cases = cases.filter(x => (str(x.Subject) + ' ' + str(x.Description)).toLowerCase().includes(ref));
  tickets = tickets.filter(x => str(x.order_id).toLowerCase() === ref);
}
cases = cases
  .sort((a, b) => {
    const p = str(a.LastModifiedDate), q = str(b.LastModifiedDate);
    return p < q ? -1 : p > q ? 1 : 0;
  })
  .reverse()
  .slice(0, 5);

const day = (t) => str(t).slice(0, 10);
const words = (st) => {
  switch (str(st).toLowerCase()) {
    case 'new': return 'received and waiting to be picked up by our team';
    case 'working':
    case 'in progress':
    case 'escalated': return 'being worked on by our team';
    case 'on hold':
    case 'waiting':
    case 'pending': return 'on hold while we wait for more information';
    case 'closed':
    case 'resolved':
    case 'done': return 'resolved by our team';
    default: return "currently marked '" + str(st) + "'";
  }
};

const lines = cases.map(x =>
  'Request "' + str(x.Subject) + '": ' + words(x.Status) +
  ' (opened ' + day(x.CreatedDate) + ', last update ' + day(x.LastModifiedDate) +
  '; reference ' + str(x.CaseNumber) + ')'
);
tickets.forEach(x => {
  lines.push('Urgent request for order ' + str(x.order_id) + ': ' + words(x.last_status) +
    ' (last update ' + str(x.updated) + ')');
});

if (lines.length === 0) {
  return [{ json: { found: 'false', count: '0', summary: 'No open requests are on record for this customer.' } }];
}
return [{ json: { found: 'true', count: String(lines.length), summary: lines.join('\n') } }];

